package com.rationportal.model; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="ration_cards") public class RationCard { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="ration_card_number", unique=true, nullable=false) private String rationCardNumber; @Column(name="card_type", nullable=false) private String cardType; @Column(name="head_of_family") private String headOfFamily; private String address; private String district; private String state; @Column(nullable=false) private String status; @Column(name="created_at", nullable=false) private LocalDateTime createdAt; @PrePersist protected void onCreate(){ if(createdAt==null) createdAt=LocalDateTime.now(); } public Long getId(){return id;} public String getRationCardNumber(){return rationCardNumber;} public void setRationCardNumber(String rationCardNumber){this.rationCardNumber=rationCardNumber;} public String getCardType(){return cardType;} public void setCardType(String cardType){this.cardType=cardType;} public String getHeadOfFamily(){return headOfFamily;} public void setHeadOfFamily(String headOfFamily){this.headOfFamily=headOfFamily;} public String getAddress(){return address;} public void setAddress(String address){this.address=address;} public String getDistrict(){return district;} public void setDistrict(String district){this.district=district;} public String getState(){return state;} public void setState(String state){this.state=state;} public String getStatus(){return status;} public void setStatus(String status){this.status=status;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime createdAt){this.createdAt=createdAt;} }
